/**
 * Заглавный экран как книга-панорама: плоские слои иллюстрации на отдельных
 * полигонах с прозрачностью.
 *
 * Каждый слой — PNG в размер кадра, поэтому при нулевом сдвиге слои складываются
 * ровно в исходную картинку. Слои стоят на разной глубине и чуть расходятся
 * (параллакс): ближний ствол уезжает сильнее, дальний лес — почти нет. Плюс
 * «дышащий» свет: тёплый/холодный сдвиг и мягкое пятно солнца, ползущее по кадру.
 */

import * as THREE from 'three';

export interface PlateOptions {
  /** Базовый путь к слоям (обычно import.meta.env.BASE_URL + 'title/layers/'). */
  base: string;
  quality: 'high' | 'medium' | 'low';
  /** Вызывается, когда дальний слой доехал и панораму можно показывать. */
  onReady?: () => void;
}

interface LayerSpec {
  name: string;
  /** Глубина в метрах сцены: больше — дальше. */
  depth: number;
}

/** Порядок и глубина слоёв: рама-стволы ближе всех, дальний лес — позади. */
const LAYERS: LayerSpec[] = [
  { name: 'forest', depth: 26 },
  { name: 'ground', depth: 15 },
  { name: 'lion', depth: 10 },
  { name: 'trunk_right', depth: 7.5 },
  { name: 'trunk_left', depth: 7 },
  { name: 'traveler', depth: 5.5 },
];

/** Доля кадра, на которую слои расходятся на опорной глубине. */
const PARALLAX = 0.02;
const PARALLAX_REFERENCE = 12;

export class PlateStack {
  private readonly root = new THREE.Group();
  private readonly plates: { mesh: THREE.Mesh; material: THREE.MeshBasicMaterial; depth: number }[] = [];
  private readonly textures: THREE.Texture[] = [];
  private readonly sun: THREE.Mesh;
  private readonly sunTexture: THREE.Texture;
  private pointer = new THREE.Vector2();
  private drift = 0;
  private base = 0;

  constructor(private readonly camera: THREE.PerspectiveCamera, options: PlateOptions) {
    this.root.name = 'titlePlates';
    const loader = new THREE.TextureLoader();

    for (const spec of LAYERS) {
      const texture = loader.load(`${options.base}${spec.name}.webp`, () => {
        if (spec.name === 'forest') options.onReady?.();
      });
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.generateMipmaps = false;
      const material = new THREE.MeshBasicMaterial({
        map: texture,
        transparent: true,
        depthWrite: false,
        fog: false,
        toneMapped: false,
      });
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), material);
      mesh.name = `plate_${spec.name}`;
      // порядок отрисовки: дальние ниже по стеку, ближние выше
      mesh.renderOrder = LAYERS.length - LAYERS.indexOf(spec);
      this.root.add(mesh);
      this.plates.push({ mesh, material, depth: spec.depth });
      this.textures.push(texture);

    }

    // мягкое пятно солнца: аддитивная плоскость, медленно ползёт по кадру
    this.sunTexture = PlateStack.sunTexture();
    const sunMaterial = new THREE.MeshBasicMaterial({
      map: this.sunTexture, transparent: true, depthWrite: false, fog: false,
      blending: THREE.AdditiveBlending, opacity: 0.18,
    });
    this.sun = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), sunMaterial);
    this.sun.name = 'plate_sun';
    this.sun.renderOrder = 0;
    this.root.add(this.sun);

    this.base = performance.now();
    this.layout();
  }

  /** Мягкое радиальное пятно — «солнце» для живописного света. */
  private static sunTexture(): THREE.Texture {
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 256;
    const context = canvas.getContext('2d')!;
    const gradient = context.createRadialGradient(128, 128, 8, 128, 128, 128);
    gradient.addColorStop(0, 'rgba(255, 232, 178, 0.95)');
    gradient.addColorStop(0.45, 'rgba(255, 206, 132, 0.35)');
    gradient.addColorStop(1, 'rgba(255, 190, 110, 0)');
    context.fillStyle = gradient;
    context.fillRect(0, 0, 256, 256);
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return texture;
  }

  get object3d(): THREE.Object3D {
    return this.root;
  }

  /** Параллакс от курсора: на телефоне просто не вызывается. */
  setPointer(x: number, y: number): void {
    this.pointer.set(x, y);
  }

  /** Переставить слои под текущий размер кадра. */
  layout(): void {
    const halfHeight = (depth: number): number =>
      Math.tan((this.camera.fov / 2) * (Math.PI / 180)) * depth;
    const direction = new THREE.Vector3();
    const right = new THREE.Vector3();
    const up = new THREE.Vector3();
    this.camera.getWorldDirection(direction);
    right.crossVectors(direction, this.camera.up).normalize();
    up.crossVectors(right, direction).normalize();

    for (const { mesh, depth } of this.plates) {
      const halfH = halfHeight(depth);
      const halfW = halfH * this.camera.aspect;
      const reach = PARALLAX * (PARALLAX_REFERENCE / depth);
      // запас 2*reach + 2 %: при сдвиге края кадра не оголяются
      const margin = 1 + reach * 2 + 0.02;
      const plane = mesh.geometry as THREE.PlaneGeometry;
      if (plane.parameters.width !== 2 * halfW * margin || plane.parameters.height !== 2 * halfH * margin) {
        mesh.geometry.dispose();
        mesh.geometry = new THREE.PlaneGeometry(2 * halfW * margin, 2 * halfH * margin);
      }
      mesh.position.copy(this.camera.position).addScaledVector(direction, depth);
      mesh.quaternion.copy(this.camera.quaternion);
    }


    const sunDepth = 9;
    const halfH = halfHeight(sunDepth);
    this.sun.geometry.dispose();
    this.sun.geometry = new THREE.PlaneGeometry(halfH * this.camera.aspect * 3.2, halfH * 2.6);
    this.sun.position.copy(this.camera.position);
    this.sun.quaternion.copy(this.camera.quaternion);
    this.sun.translateZ(-sunDepth);
  }

  /** Покадрово: параллакс и «дыхание» света. */
  update(time: number): void {
    // медленный дрейф камеры + реакция на курсор
    const driftX = Math.sin(time * 0.11) * 0.55 + Math.sin(time * 0.37) * 0.2;
    const driftY = Math.cos(time * 0.09) * 0.5 + Math.sin(time * 0.23) * 0.18;
    const pointerX = this.pointer.x * 0.7;
    const pointerY = this.pointer.y * 0.5;
    this.drift = Math.sin(time * 0.13) * 0.5 + 0.5;

    const direction = new THREE.Vector3();
    const right = new THREE.Vector3();
    const up = new THREE.Vector3();
    this.camera.getWorldDirection(direction);
    right.crossVectors(direction, this.camera.up).normalize();
    up.crossVectors(right, direction).normalize();
    const halfHeight = (depth: number): number =>
      Math.tan((this.camera.fov / 2) * (Math.PI / 180)) * depth;

    for (const { mesh, material, depth } of this.plates) {
      const reach = PARALLAX * (PARALLAX_REFERENCE / depth);
      const ndcX = (driftX + pointerX) * reach;
      const ndcY = (driftY + pointerY) * reach * 0.7;
      const halfH = halfHeight(depth);
      mesh.position.copy(this.camera.position).addScaledVector(direction, depth)
        .addScaledVector(right, ndcX * halfH * this.camera.aspect)
        .addScaledVector(up, ndcY * halfH);
      // свет «дышит»: тёплый ↔ холодный, дальние слои сильнее
      const warm = Math.sin(time * 0.13) * 0.5 + 0.5;
      const shift = (depth > 20 ? 0.10 : 0.06) * (warm - 0.5) * 2;
      material.color.setRGB(1 + shift, 1 + shift * 0.35, 1 - shift * 0.8);
    }


    const sunMaterial = this.sun.material as THREE.MeshBasicMaterial;
    sunMaterial.opacity = 0.14 + Math.sin(time * 0.17) * 0.06;
    this.sun.position.x += Math.sin(time * 0.05) * 0.02;
  }

  dispose(): void {
    for (const { mesh } of this.plates) mesh.geometry.dispose();
    for (const { material } of this.plates) material.dispose();
    for (const texture of this.textures) texture.dispose();
    this.sun.geometry.dispose();
    (this.sun.material as THREE.Material).dispose();
    this.sunTexture.dispose();
    this.root.removeFromParent();
  }
}
